package com.tracker.config;
import com.tracker.service.JwtService; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException;
@Component public class FacultyAccessFilter extends OncePerRequestFilter {private final JwtService jwt;public FacultyAccessFilter(JwtService j){jwt=j;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{if(req.getRequestURI().startsWith(req.getContextPath()+"/api/admin/")){Authentication a=SecurityContextHolder.getContext().getAuthentication();String h=req.getHeader("Authorization");boolean verified=a!=null&&a.isAuthenticated()&&h!=null&&h.startsWith("Bearer ")&&jwt.facultyVerified(h.substring(7));if(!verified){res.sendError(HttpServletResponse.SC_FORBIDDEN,"Faculty verification required");return;}}chain.doFilter(req,res);}}
